<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\OAuth\Authentication\Domain\Gateway\RemoteJwksFetcher;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\RequestObjectValidator;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Jose\Component\Core\AlgorithmManager;
use Jose\Component\KeyManagement\JWKFactory;
use Jose\Component\Signature\Algorithm\RS256;
use Jose\Component\Signature\Algorithm\ES256;
use Jose\Component\Signature\Algorithm\PS256;
use Jose\Component\Signature\JWSBuilder;
use Jose\Component\Signature\Serializer\CompactSerializer;
use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\integration\Features\OAuth\Stub\InMemoryReplayJti;

#[AllowMockObjectsWithoutExpectations]

final class RequestObjectValidatorUnitTest extends TestCase
{
    private const string TENANT = 'tenant1';
    private const string ISSUER = 'https://idp.example/oauth/openid/tenant1';

    public function testValidateReturnsPayloadForValidRs256RequestObject(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(['scope' => 'openid']), 'RS256');

        $payload = $this->buildValidator()->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);

        $this->assertSame('client-123', $payload['client_id']);
        $this->assertSame('openid', $payload['scope']);
    }

    public function testValidateAcceptsOtherAdvertisedSigningAlgorithms(): void
    {
        foreach (['ES256', 'PS256'] as $alg) {
            [$privateJwk, $publicJwkJson] = $this->buildJwks($alg);
            $jwt = $this->buildJwt($privateJwk, $this->claims(), $alg);
            $client = new ClientData('client-123', ['code'], true, [], 3600, $alg, null, $publicJwkJson);

            $payload = $this->buildValidator()->validate($jwt, $client, self::TENANT, self::ISSUER);
            $this->assertSame('client-123', $payload['client_id'], $alg);
        }
    }

    public function testValidateThrowsWhenSignatureIsInvalid(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(), 'RS256');
        $invalid = substr($jwt, 0, -1) . (str_ends_with($jwt, 'a') ? 'b' : 'a');

        $this->expectException(InvalidArgumentException::class);
        $this->buildValidator()->validate($invalid, $this->client($publicJwkJson), self::TENANT, self::ISSUER);
    }

    public function testValidateThrowsWhenAlgIsNone(): void
    {
        $header = rtrim(strtr(base64_encode('{"alg":"none"}'), '+/', '-_'), '=');
        $payload = rtrim(strtr(base64_encode((string) json_encode($this->claims())), '+/', '-_'), '=');

        $this->expectException(InvalidArgumentException::class);
        $this->buildValidator()->validate($header . '.' . $payload . '.', new ClientData('client-123', ['code'], true), self::TENANT, self::ISSUER);
    }

    /**
     * Claims that do not bind the object to this client, this tenant and a short, current window.
     */
    public static function rejectedClaims(): array
    {
        return [
            'client_id of another client' => [['client_id' => 'other-client']],
            'iss of another client' => [['iss' => 'other-client']],
            'without iss' => [['iss' => null]],
            'aud of another tenant' => [['aud' => 'https://idp.example/oauth/openid/tenant2']],
            'without aud' => [['aud' => null]],
            'expired' => [['exp' => time() - 120]],
            'without exp' => [['exp' => null]],
            'lifetime beyond one hour' => [['exp' => time() + 7200]],
            'not yet valid' => [['nbf' => time() + 600]],
            'issued in the future' => [['iat' => time() + 600]],
            'without jti' => [['jti' => null]],
        ];
    }

    #[DataProvider('rejectedClaims')]
    public function testValidateRejectsClaims(array $overrides): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, array_filter($this->claims($overrides), static fn (mixed $v): bool => $v !== null), 'RS256');

        $this->expectException(InvalidArgumentException::class);
        $this->expectExceptionMessage('invalid_request_object');
        $this->buildValidator()->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);
    }

    public function testValidateAcceptsAudienceListNamingTheIssuer(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(['aud' => ['https://other.example', self::ISSUER]]), 'RS256');

        $payload = $this->buildValidator()->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);
        $this->assertSame('client-123', $payload['client_id']);
    }

    public function testValidateRejectsReplayedRequestObject(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(), 'RS256');
        $validator = $this->buildValidator();
        $validator->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);

        $this->expectException(InvalidArgumentException::class);
        $validator->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);
    }

    public function testJtiIsKeptWhileTheObjectIsStillAcceptedWithinTheLeeway(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $exp = time() + 300;
        $jwt = $this->buildJwt($privateJwk, $this->claims(['exp' => $exp]), 'RS256');
        $replays = $this->createMock(\Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\ReplayJtiGateway::class);
        $replays->expects($this->once())
            ->method('consume')
            ->with(
                self::TENANT,
                'client-123',
                \Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\ReplayPurpose::RequestObject,
                $this->isString(),
                $this->callback(static fn (DateTimeImmutable $keptUntil): bool => $keptUntil->getTimestamp() === $exp + 30)
            )
            ->willReturn(true);

        (new RequestObjectValidator($this->createMock(RemoteJwksFetcher::class), $replays))
            ->validate($jwt, $this->client($publicJwkJson), self::TENANT, self::ISSUER);
    }

    public function testValidateFetchesJwksFromUriWhenInlineMissing(): void
    {
        [$privateJwk, $publicJwkJson] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(), 'RS256');

        $jwks = $this->createMock(RemoteJwksFetcher::class);
        $jwks->expects($this->once())
            ->method('fetch')
            ->with(self::TENANT, 'client-123', 'https://client.example/jwks')
            ->willReturn(json_decode($publicJwkJson, true));
        $client = new ClientData('client-123', ['code'], true, [], 3600, 'RS256', 'https://client.example/jwks', null);

        $payload = $this->buildValidator($jwks)->validate($jwt, $client, self::TENANT, self::ISSUER);
        $this->assertSame('client-123', $payload['client_id']);
    }

    public function testValidateMapsRefusedJwksUriToInvalidRequestObject(): void
    {
        [$privateJwk] = $this->buildRsaJwks();
        $jwt = $this->buildJwt($privateJwk, $this->claims(), 'RS256');
        $jwks = $this->createMock(RemoteJwksFetcher::class);
        $jwks->method('fetch')->willThrowException(new InvalidArgumentException('jwks_uri host is not a public address'));
        $client = new ClientData('client-123', ['code'], true, [], 3600, 'RS256', 'https://10.0.0.5/jwks', null);

        $this->expectException(InvalidArgumentException::class);
        $this->expectExceptionMessage('invalid_request_object');
        $this->buildValidator($jwks)->validate($jwt, $client, self::TENANT, self::ISSUER);
    }

    private function claims(array $overrides = []): array
    {
        return array_merge([
            'client_id' => 'client-123',
            'iss' => 'client-123',
            'aud' => self::ISSUER,
            'iat' => time(),
            'exp' => time() + 300,
            'jti' => bin2hex(random_bytes(8)),
        ], $overrides);
    }

    private function client(string $jwksJson): ClientData
    {
        return new ClientData('client-123', ['code'], true, [], 3600, 'RS256', null, $jwksJson);
    }

    private function buildJwt(object $privateJwk, array $payload, string $alg): string
    {
        $algorithm = match ($alg) {
            'ES256' => new ES256(),
            'PS256' => new PS256(),
            default => new RS256(),
        };
        $builder = new JWSBuilder(new AlgorithmManager([$algorithm]));
        $jws = $builder->create()
            ->withPayload((string) json_encode($payload))
            ->addSignature($privateJwk, ['alg' => $alg])
            ->build();

        return (new CompactSerializer())->serialize($jws, 0);
    }

    private function buildRsaJwks(string $alg = 'RS256'): array
    {
        $resource = openssl_pkey_new(['private_key_type' => OPENSSL_KEYTYPE_RSA, 'private_key_bits' => 2048]);
        if ($resource === false) {
            $this->fail('Unable to generate rsa key');
        }

        openssl_pkey_export($resource, $privatePem);
        $details = openssl_pkey_get_details($resource);
        $publicPem = is_array($details) ? (string) ($details['key'] ?? '') : '';

        $privateJwk = JWKFactory::createFromKey($privatePem, null, ['kid' => 'k1', 'alg' => $alg, 'use' => 'sig']);
        $publicJwk = JWKFactory::createFromKey($publicPem, null, ['kid' => 'k1', 'alg' => $alg, 'use' => 'sig']);
        $jwksJson = (string) json_encode(['keys' => [$publicJwk->all()]]);

        return [$privateJwk, $jwksJson];
    }

    private function buildJwks(string $alg): array
    {
        if ($alg !== 'ES256') {
            return $this->buildRsaJwks($alg);
        }

        $resource = openssl_pkey_new(['private_key_type' => OPENSSL_KEYTYPE_EC, 'curve_name' => 'prime256v1']);
        if ($resource === false) {
            $this->fail('Unable to generate EC key');
        }
        openssl_pkey_export($resource, $privatePem);
        $details = openssl_pkey_get_details($resource);
        $publicPem = is_array($details) ? (string) ($details['key'] ?? '') : '';
        $privateJwk = JWKFactory::createFromKey($privatePem, null, ['kid' => 'k1', 'alg' => $alg, 'use' => 'sig']);
        $publicJwk = JWKFactory::createFromKey($publicPem, null, ['kid' => 'k1', 'alg' => $alg, 'use' => 'sig']);
        return [$privateJwk, (string) json_encode(['keys' => [$publicJwk->all()]])];
    }

    private function buildValidator(?RemoteJwksFetcher $jwks = null): RequestObjectValidator
    {
        return new RequestObjectValidator($jwks ?? $this->createMock(RemoteJwksFetcher::class), new InMemoryReplayJti());
    }
}
